<script setup>
import {FormField} from './ui/form-field'
import UiSelect from './ui/select/Select.vue'
import {Button as UiButton} from './ui/button'
import {DatePicker,DateRangePicker} from './ui/date-picker'
import {useScope} from '../store'
// Company / farm / block / plot / cycle / date filters above every /lotus screen. Emits change after scope is edited.
defineProps({page:String,busy:Boolean,land:{type:Boolean,default:true},farmVisible:{type:Boolean,default:true},options:{type:Object,required:true},companies:{type:Array,required:true},farms:{type:Array,required:true}})
defineEmits(['change','refresh'])
const scope=useScope()
</script>
<template><div class="scope-picker"><FormField v-if="companies.length>1" label="Công ty" v-slot="f"><UiSelect v-bind="f" v-model="scope.company" @change="scope.clearBelow('company');$emit('change')"><option value="">Tất cả công ty</option><option v-for="c in companies" :key="c">{{c}}</option></UiSelect></FormField><FormField v-if="farmVisible" label="Vườn" v-slot="f"><UiSelect v-bind="f" v-model="scope.farm" @change="scope.clearBelow('farm');$emit('change')"><option value="">Tất cả vườn</option><option v-for="f in farms" :key="f.name" :value="f.name">{{f.farm_name||f.name}}</option></UiSelect></FormField><FormField v-if="land&&options.zones?.length" label="Khu" v-slot="f"><UiSelect v-bind="f" v-model="scope.zone" @change="scope.clearBelow('zone');$emit('change')"><option value="">Tất cả khu</option><option v-for="z in options.zones" :key="z" :value="z">Khu {{z}}</option></UiSelect></FormField><FormField v-if="land&&options.blocks?.length" label="Lô chăm sóc" v-slot="f"><UiSelect v-bind="f" v-model="scope.block" @change="scope.clearBelow('block');$emit('change')"><option value="">Tất cả lô</option><option v-for="b in options.blocks" :key="b.name" :value="b.name">{{b.block_name||b.name}}</option></UiSelect></FormField><FormField v-if="land&&!['forecast','plan-norm','map'].includes(page)&&options.cycles?.length" label="Vụ" v-slot="f"><UiSelect v-bind="f" v-model="scope.cycle" @change="$emit('change')"><option value="">Tất cả vụ</option><option v-for="c in options.cycles" :key="c.name" :value="c.name">{{c.name}} · {{c.cycle_no}}</option></UiSelect></FormField><FormField v-if="page!=='map'" :label="page==='forecast'?'Bắt đầu kế hoạch':'Ngày'" v-slot="f"><DatePicker v-bind="f" v-model="scope.date" :label="page==='forecast'?'Bắt đầu kế hoạch':'Ngày'" :clearable="false" @change="scope.from_date='';scope.to_date='';$emit('change')" /></FormField><FormField v-if="!['map','trace','admin/settings','forecast'].includes(page)" label="Từ ngày – đến ngày" v-slot="f"><DateRangePicker v-bind="f" v-model:from="scope.from_date" v-model:to="scope.to_date" label="Từ ngày – đến ngày" @change="$emit('change')" /></FormField><UiButton variant="outline" :loading="busy" @click="$emit('refresh')">Cập nhật</UiButton></div></template>
